---
/**
 * index.astro — the Logos52 home, matched to the original Quartz HomeLanding: compact, narrow
 * (~original --pageWidth), left-aligned hero, inline search, constellation + legend, Open
 * questions / Today's retrieval, Start here (intent doors), and three hub-list columns.
 */
import { existsSync, readFileSync } from 'node:fs';
import { getCollection } from 'astro:content';

import Base from '../layouts/Base.astro';
import DomainChip from '../components/DomainChip.astro';
import Constellation from '../components/Constellation.astro';
import Icon from '../components/Icon.astro';
import { slugifyFilePath, slugToUrl } from '../lib/slug';
import { DOMAIN_LABELS, type Domain } from '../lib/types';
import { DOMAIN_ICONS } from '../lib/icons';

interface HomeData {
  hero?: { title?: string; lede?: string };
  questions?: string[];
  todaysRetrieval?: { kind?: string; title?: string; prompt?: string; queueCount?: number; slug?: string };
}
const HOME_JSON = 'kb-astro/site-data/home.json';
let home: HomeData | null = null;
try {
  if (existsSync(HOME_JSON)) home = JSON.parse(readFileSync(HOME_JSON, 'utf8')) as HomeData;
} catch {
  home = null;
}

const notes = await getCollection('notes');
const hero = home?.hero ?? {
  title: 'A second brain for learning systems & agentic engineering',
  lede: 'Linked notes on learning systems, language study, and software work with LLM agents.',
};
// "Currently" — a short now-band: what I'm building / learning / reading / chewing on. Hand-curated;
// edit these freely. (Replaced the Open-questions + Today's-retrieval pulse cards.)
// "Top of mind" — open questions about where AI is going and how to shape it (personal + society),
// plus one standing "Personal items" entry gathering the personal wings (added 2026-07-21).
// Pose the question; link to the note that addresses it. Standard: 02 - System/Writing Standards.md
// → High-Signal Front-Facing Pages → Open Questions Stay Open. Edit freely; keep them in-lane.
type Mind = { q: string; links: { t: string; href: string }[] };
const L = (t: string, p: string) => ({ t, href: slugToUrl(slugifyFilePath(p)) });
const topOfMind: Mind[] = [
  {
    q: 'How do you build trust with your agents?',
    links: [
      L('Poteto Paved Path', 'wiki/Systems/Agentic Workflows/Poteto Paved Path'),
      L('Karpathy LLM-Wiki', 'wiki/Systems/Agentic Workflows/Karpathy LLM-Wiki'),
    ],
  },
  {
    q: 'Arcs give a character a moral core first. Later arcs charge the moral core against something the character loves. Do stories people love work that way?',
    links: [
      L('Tsumugu', 'wiki/Tsumugu/Tsumugu'),
      L('The Moral Core', 'wiki/Story Craft/The Moral Core'),
      L('Arc Types', 'wiki/Story Craft/Arc Types'),
    ],
  },
  {
    q: 'Exercise, clothing, and travel pages, written with my personal taste in mind',
    links: [
      L('Movement as Accretion', 'wiki/Fitness/Movement as Accretion'),
      L('The Personal Uniform', 'wiki/Fashion/The Personal Uniform'),
      L('Warm Countries, Cold Countries', 'wiki/Travel/Warm Countries, Cold Countries'),
      L('Reading as Local', 'wiki/Travel/Reading as Local'),
    ],
  },
  {
    q: 'How do you check a personal belief? These pages follow the logic of a political opinion, and its second-order effects.',
    links: [
      L('Worldviews & the Political Order', 'wiki/Worldviews & the Political Order/Worldviews & the Political Order'),
      L('Validity and Truth', 'wiki/Worldviews & the Political Order/Validity and Truth'),
      L('Positions', 'personal/2026-08-17-positions'),
    ],
  },
];
// THE FOUR-CAP (Wedge's standing command, re-issued 2026-08-11 after the list drifted to six):
// Top of mind holds exactly 4. A new entry enters only with the lowest retiring in the same edit,
// archived below like the others. The guard is fail-closed — the build dies before the list grows.
if (topOfMind.length > 4)
  throw new Error(`Top of mind holds 4 entries (Wedge's cap); found ${topOfMind.length} — retire the lowest before adding.`);
// Retired from the card 2026-07-17 (Wedge: the list must not grow — lowest entry archived, not deleted):
//   q: 'If a generation offloads its thinking to AI, what are the second-order effects?'
//   links: Epistemic Exceptionalism (wiki/Red Team) · The Shortcut Problem (wiki/Concepts) · The Age of Nonlinear Returns (wiki/Concepts)
// Retired 2026-07-21 (same rule — the Personal items entry came in, lowest went out):
//   q: 'Where leaning on AI builds understanding'
//   links: Understanding Bottleneck (wiki/Concepts) · Are You Thinking, or Just Consuming (wiki/Concepts) · The Screen Inferiority Effect (wiki/Concepts)
// Retired 2026-08-06 (same rule — the Least-Cost Interpretation entry came in, lowest went out):
//   q: 'Whether the line between what humans and models own is fixed, or keeps shifting'
//   links: Human vs AI Capability Lens (wiki/Concepts) · Higher-Order Generativity vs Judgment (wiki/Concepts) · The AI Industrial Revolution (wiki/Concepts) · The Floor Rose, the Ceiling Is the Job (journal)
// Retired 2026-08-11 (the four-cap enforced — list had drifted to six, pruned back, lowest two out):
//   q: 'What stays human as the models match generativity'
//   links: Human vs AI Capability Lens (wiki/Concepts) · Higher-Order Generativity vs Judgment (wiki/Concepts) · A Motorcycle for the Mind (wiki/Concepts) · The AI Industrial Revolution (wiki/Concepts) · Automation and the Job Iceberg (wiki/Systems/AI & Agentic Systems)
//   q: 'What changes when the deliberate reasoning inside a model can be read and steered directly'
//   links: Global Workspace and J-space (wiki/Concepts) · The workspace a language model thinks in (journal/2026-07-07) · Human vs AI Capability Lens (wiki/Concepts)
// Retired 2026-08-17 (Worldviews & the Political Order entered; lowest out):
//   q: 'Whether the inner life that makes a written character read as a person is something a model can author'
//   links: The Wound and the Lie · Round Characters and the Telling Detail · Human vs AI Capability Lens · Story Craft

// Intent doors ("Start here") — route a visitor by intent, not topic. slug → a note path
// (resolved via cardHref); the graph door uses a direct href. Titles/subs are mined from each
// destination note (concrete, note-grounded). Colors: Understand/Apply ride DS theme tokens
// (--violet / --cool, auto-lift in dark); Learn/Decode/Explore are seeded in .start-here CSS with a
// dark override. Five doors cover all three hero domains: learning · agentic · language.
type Door = { intent: string; icon: string; title: string; sub: string; color: string; slug?: string; href?: string };
const startHere: Door[] = [
  { intent: 'Understand', icon: 'ti-bulb',      title: 'What Engineers Are Judged On',            sub: 'Now AI agents write much of the code, so an engineer is judged on the setup the engineer builds.',      color: 'var(--i-understand)', slug: 'wiki/Concepts/The-AI-Industrial-Revolution' },
  { intent: 'Apply',      icon: 'ti-robot',     title: 'Vibe Coding',              sub: 'You ask an AI agent for an app in everyday language, and the agent writes the code and runs it. Soon all coding will become vibe coding.',          color: 'var(--i-apply)',      slug: 'wiki/Systems/AI & Agentic Systems/Vibe-Coding' },
  { intent: 'Learn',      icon: 'ti-school',    title: 'Does a Study Technique Work?',              sub: 'A technique such as notes or a mind map works only if it makes you process the material in your mind.',     color: 'var(--i-learn)',      slug: 'wiki/Syntheses/Are-You-Learning,-or-Just-Using-Techniques' },
  { intent: 'Decode',     icon: 'ti-language',  title: 'How Chinese Characters Are Built',    sub: 'Each character is made of smaller parts, and each part has a different function.', color: 'var(--i-decode)',     slug: 'wiki/Language/Chinese/How-Chinese-Characters-Work' },
  { intent: 'Explore',    icon: 'ti-affiliate', title: 'Map of the Site',           sub: 'Every node is an article on the site, and a line between two nodes shows a relationship.',                color: 'var(--i-explore)',    href: '/map/' },
];

type Hub = { title: string; icon: string; color: string; slug: string; tag?: string; countPrefix?: string };
// Hub icon colors now draw from the cool-jewel domain palette (var(--d-*)), so they
// match the theme and adapt across light/charcoal. Each column spreads the 6 domain
// hues for rhythm rather than repeating the old ad-hoc brights.
const dimensionHubs: Hub[] = [
  { title: 'Deep Processing', icon: 'ti-affiliate', color: 'var(--d-learning)', slug: 'wiki/Dimensions/Deep-Processing', tag: 'deep-processing' },
  { title: 'Retrieval', icon: 'ti-circle-arrow-up', color: 'var(--d-mind)', slug: 'wiki/Dimensions/Retrieval', tag: 'retrieval' },
  { title: 'Self-Regulation', icon: 'ti-steering-wheel', color: 'var(--d-focus)', slug: 'wiki/Dimensions/Self-Regulation', tag: 'self-regulation' },
  { title: 'Self-Management', icon: 'ti-settings', color: 'var(--d-gen)', slug: 'wiki/Dimensions/Self-Management', tag: 'self-management' },
  { title: 'Mindset', icon: 'ti-brain', color: 'var(--d-agentic)', slug: 'wiki/Dimensions/Mindset', tag: 'mindset' },
];
const lifeHubs: Hub[] = [
  { title: 'Health', icon: 'ti-heartbeat', color: 'var(--d-mind)', slug: 'wiki/Dimensions/Self-Management', countPrefix: 'wiki/Dimensions/Self-Management' },
  { title: 'Money', icon: 'ti-wallet', color: 'var(--d-gen)', slug: 'wiki/Money/Money, Condensed', countPrefix: 'wiki/Money' },
  { title: '中文', icon: 'ti-language', color: 'var(--d-language)', slug: 'wiki/Language/Chinese/How-Chinese-Characters-Work', countPrefix: 'wiki/Language/Chinese' },
  { title: 'Minimalism', icon: 'ti-box', color: 'var(--d-focus)', slug: 'wiki/Minimalism/Minimalism-as-Systems-Design', countPrefix: 'wiki/Minimalism' },
  { title: 'Condensed Notes', icon: 'ti-book-2', color: 'var(--d-learning)', slug: 'wiki/Syntheses/Learning, Condensed', countPrefix: 'wiki/Syntheses' },
];
const executionHubs: Hub[] = [
  { title: 'Agentic Engineering', icon: 'ti-robot', color: 'var(--d-agentic)', slug: 'wiki/Systems/AI & Agentic Systems/Agentic-Engineering', countPrefix: 'wiki/Systems/AI & Agentic Systems' },
  { title: 'Learning Systems', icon: 'ti-network', color: 'var(--d-learning)', slug: 'wiki/Syntheses/Are-You-Learning,-or-Just-Using-Techniques', countPrefix: 'wiki/Syntheses' },
  { title: 'Focus Management', icon: 'ti-target', color: 'var(--d-focus)', slug: 'wiki/Self-Management/Flow-State', countPrefix: 'wiki/Self Management' },
  { title: 'Decision Making', icon: 'ti-checklist', color: 'var(--d-gen)', slug: 'wiki/Decision-Making/Decision-Making', countPrefix: 'wiki/Decision Making' },
  { title: 'Generativity', icon: 'ti-bulb', color: 'var(--d-mind)', slug: 'wiki/Concepts/Higher-Order-Generativity-vs-Higher-Order-Judgment', countPrefix: 'wiki/Concepts' },
  { title: 'Worldviews', icon: 'ti-scale', color: 'var(--d-mind)', slug: 'wiki/Worldviews & the Political Order/Worldviews & the Political Order', countPrefix: 'wiki/Worldviews & the Political Order' },
];
const hubColumns = [
  { title: 'Five Dimensions', items: dimensionHubs },
  { title: 'Life Systems', items: lifeHubs },
  { title: 'Knowledge & Execution', items: executionHubs },
];

// "Project Updates" — a foot-of-page changelog of what I'm currently building, newest first.
// Grouped by date; each line links to the note that carries the work. slug → a note path
// (resolved via cardHref below).
type Update = { title: string; blurb: string; slug: string };
type UpdateDay = { date: string; updates: Update[] };
const projectUpdates: UpdateDay[] = [
  {
    date: '2026-09-22',
    updates: [
      {
        title: 'Poteto Paved Path',
        blurb:
          'An agent copies a shortcut left in a file. A correction of the shortcut goes into the file, or into a check that fails a build, before the next agent extends the shortcut.',
        slug: 'wiki/Systems/Agentic Workflows/Poteto Paved Path',
      },
      {
        title: 'Karpathy LLM-Wiki',
        blurb:
          'A question against a pile of files makes a model search the pile again and save nothing. The model then writes each source into pages, and the next question starts from the pages.',
        slug: 'wiki/Systems/Agentic Workflows/Karpathy LLM-Wiki',
      },
    ],
  },
  {
    date: '2026-09-16',
    updates: [
      {
        title: 'Argument Validation',
        blurb:
          'Valid means a conclusion follows from facts an argument states. Sound means the conclusion follows and the facts are true. Each test works on any argument.',
        slug: 'wiki/Argument Validation/Argument Validation',
      },
      {
        title: 'East Asian Exams - The Arms Race',
        blurb:
          "One exam at about age 18 ranks students against each other for university. A student's rank on the exam still sets pay decades later. Tutoring by one family forces tutoring by the rest.",
        slug: 'wiki/Worldviews & the Political Order/East Asian Exams - The Arms Race',
      },
    ],
  },
];

const tagCount = new Map<string, number>();
for (const n of notes) {
  const raw = (n.data as Record<string, unknown>).tags;
  const tags = Array.isArray(raw) ? raw.map(String) : raw ? [String(raw)] : [];
  for (let t of tags) {
    t = t.trim().toLowerCase().replace(/\s+/g, '-');
    if (t) tagCount.set(t, (tagCount.get(t) ?? 0) + 1);
  }
}
const slugs = notes.map((n) => n.id);
function prefixCount(rawPrefix: string): number {
  const base = slugifyFilePath(rawPrefix);
  let c = 0;
  for (const s of slugs) if (s === base || s.startsWith(base + '/')) c++;
  return c;
}
function hubCount(h: Hub): number {
  if (h.tag && tagCount.has(h.tag)) return tagCount.get(h.tag)!;
  if (h.countPrefix) return prefixCount(h.countPrefix);
  return prefixCount(h.slug.replace(/\/[^/]+$/, ''));
}
const hubHref = (slug: string) => slugToUrl(slugifyFilePath(slug));
const cardHref = (slug: string) => slugToUrl(slugifyFilePath(slug));
const chipDomains: Domain[] = ['learning', 'agentic', 'language', 'focus', 'mind', 'gen'];
