/**
 * Note.astro — the per-note page layout.
 * Replicates the DS NotePage (ui_kits/knowledge-base/screens.jsx): a two-column
 * grid `minmax(0,1fr) 240px` inside the 1080px container, with
 *   left  = <article data-pagefind-body> : mono breadcrumb, Ming <h1>, meta row
 *           (domain-colored pill type tag + "updated …"), then the prose <slot/>
 *           in the Ming serif at max ~64ch.
 *   right = sticky aside rail (top:80px) = constellation neighborhood + Toc + Backlinks.
 *
 * Wraps Base (which owns <html data-accent="violet">, the DS css imports, the
 * no-flash theme script, Chrome + Footer). All tokens are DS custom properties.
 */
import Base from './Base.astro';
import Toc from '../components/Toc.astro';
import Backlinks from '../components/Backlinks.astro';
import Constellation from '../components/Constellation.astro';
import type { Domain, GraphData, Backlink } from '../lib/types';

interface Heading {
  depth: number;
  text: string;
  slug: string;
}

interface Props {
  title: string;
  type?: string;
  /** Frontmatter description or blurb, shown under the title and used as the meta description. */
  description?: string;
  updated?: string;
  domain: Domain | string;
  slug: string;
  headings: Heading[];
  backlinks: Backlink[];
  /** Unused now — the local graph slices /graph.json client-side. Kept so callers don't break. */
  local?: GraphData;
  active?: string;
}

const { title, type, description, updated, domain, slug, headings, backlinks, active } = Astro.props;

// Breadcrumb from the folder slug: "wiki/Concepts/Higher-Order-Generativity" →
// "wiki / Concepts / Higher-Order Generativity" (DS .crumb / NotePage breadcrumb).
const crumbParts = slug
  .replace(/^\/+/, '')
  .replace(/\/+$/, '')
  .split('/')
  .filter(Boolean)
  .map((p) => p.replace(/--and--/g, ' & ').replace(/-+/g, ' '));
const breadcrumb = crumbParts.length ? crumbParts.join(' / ') : title;
// Each crumb is a link (owner, 2026-09-05). A folder crumb lists that folder.
// journal, personal, and projects keep their section landings. The page title stays plain text.
// journal / personal / projects keep their section landings.
const LANDING: Record<string, string> = {
  journal: '/journal/',
  personal: '/personal/',
  projects: '/projects/',
  notes: '/notes/',
};
const slugParts = slug.replace(/^\/+/, '').replace(/\/+$/, '').split('/').filter(Boolean);
const crumbs = slugParts.map((part, i) => {
  const label = part.replace(/--and--/g, ' & ').replace(/-+/g, ' ');
  if (i === slugParts.length - 1) return { label, href: null as string | null };
  if (i === 0 && LANDING[part]) return { label, href: LANDING[part] };
  return { label, href: `/folder/${slugParts.slice(0, i + 1).join('/')}/` };
});

const domainVar = `var(--d-${domain})`;
const hasAside = true;
---

<Base title={title} description={description || (updated ? `Updated ${updated}` : undefined)} active={active}>
  <main class="kb-note-main">
    <div class="kb-note-grid">
      <article
        data-pagefind-body
        data-pagefind-meta={`domain:${domain}`}
        data-pagefind-meta={`title:${title}`}
      >
        <div class="kb-crumb" data-pagefind-ignore aria-label={breadcrumb}>
          {
            crumbs.length
              ? crumbs.map((c, i) => (
                  <Fragment>
                    {i > 0 && <span class="kb-crumb-sep"> / </span>}
                    {c.href ? <a href={c.href}>{c.label}</a> : <span>{c.label}</span>}
                  </Fragment>
                ))
              : title
          }
        </div>
        {/* The markdown body carries its own leading <h1> (hidden below by `.kb-prose > h1`), and
            Pagefind indexes hidden text — so without this ignore every excerpt opened by saying the
            title twice. The row's title comes from data-pagefind-meta, not from this element. */}
        <h1 class="kb-note-title" data-pagefind-ignore>{title}</h1>
        <div class="kb-note-meta" data-pagefind-ignore>
          {
            type && (
              <span class="kb-type-tag" style={`border-color:${domainVar};color:${domainVar}`}>
                {type}
              </span>
            )
          }
          {updated && <span>updated {updated}</span>}
        </div>
        {description && <p class="kb-note-dek" data-pagefind-ignore>{description}</p>}
        <div class="kb-prose">
          <slot />
        </div>
      </article>

      {
        hasAside && (
          <aside class="kb-note-aside">
            <div class="kb-localgraph-wrap" aria-hidden="true">
              <Constellation mode="local" seeds={[slug]} hops={2} height="118px" />
            </div>
            <Toc headings={headings} />
            <Backlinks items={backlinks} />
          </aside>
        )
      }
    </div>
