+async function waitFor(send, expr, ms = 12000) {
+  const start = Date.now();
+  let last;
+  while (Date.now() - start < ms) {
+    try {
+      last = await evaluate(send, `(() => { try { return (${expr}); } catch (e) { return null; } })()`);
+      if (last) return last;
+    } catch (e) {
+      last = String(e);
+    }
+    await sleep(200);
