+        blurbText: s.querySelector('.domain__blurb')?.textContent.trim().slice(0, 80) || null,
+      })),
+      fallback: document.querySelector('.constellation__fallback')?.textContent.trim() || null,
+    })`,
+  );
+  await sleep(800);
+  await shot(send, '09-map');
+  report.features.map = { state };
+  if (state.h1 !== 'The vault') fail(feature, 'h1', state);
+  if (!state.mapOn) fail(feature, 'Map not .on', state);
+  if (state.mode !== 'full') fail(feature, 'mode', state);
+  if (!state.domainLabels) fail(feature, 'missing data-domain-labels', state);
+  if (!state.canvas) fail(feature, 'no canvas', state);
+  if (state.six !== 'The six domains') fail(feature, 'six domains heading', state);
+  if (state.fallback) fail(feature, 'graph fallback', state);
+  const learning = state.domains.find((d) => d.href === '/domains/learning/');
+  if (!learning) fail(feature, 'no learning domain link', state);
+  note(feature, 'map snapshot', state);
+
+  await clickExpr(
+    send,
+    `[...document.querySelectorAll('section.domain h3 a')].find(a => a.getAttribute('href')==='/domains/learning/')`,
+  );
+  const domain = await waitFor(
+    send,
+    `/^\\/domains\\/learning\\/?$/.test(location.pathname) && document.querySelector('h1') && ({
+      path: location.pathname,
+      h1: document.querySelector('h1').innerText.replace(/\\s+/g,' ').trim(),
+      moc: document.querySelectorAll('ul.moc a').length,
+      notesOn: [...document.querySelectorAll('a.kb-nav__link')].find(a => a.textContent.trim()==='Notes')?.classList.contains('on') || false,
+      mapOn: [...document.querySelectorAll('a.kb-nav__link')].find(a => a.textContent.trim()==='Map')?.classList.contains('on') || false,
+      kind: document.querySelector('a.head__kind')?.getAttribute('href'),
+    })`,
+  );
+  await sleep(500);
+  await shot(send, '10-domain-learning');
+  report.features.map.domain = domain;
+  if (!/Learning/.test(domain.h1)) fail(feature, 'domain h1', domain);
+  if (domain.moc < 1) fail(feature, 'empty moc', domain);
+  if (!domain.notesOn) fail(feature, 'Notes not .on on domain page', domain);
+  if (domain.mapOn) fail(feature, 'Map still .on on domain page', domain);
+  if (domain.kind !== '/map/') fail(feature, 'head kind href', domain);
+  note(feature, 'domain landed', domain);
+}
+
+async function main() {
+  startChrome();
+  const page = await waitJson();
+  const ws = new WebSocket(page.webSocketDebuggerUrl);
+  await new Promise((resolve, reject) => {
+    ws.addEventListener('open', resolve);
+    ws.addEventListener('error', () => reject(new Error('ws error')));
+  });
+  const send = cdp(ws);
+  await send('Page.enable');
+  await send('Runtime.enable');
+  try {
+    await home(send);
+    await wikiIndex(send);
+    await wikiPage(send);
+    await search(send);
+    await map(send);
+  } catch (e) {
+    report.failures.push({ feature: 'harness', msg: String(e.stack || e) });
+    console.error(e);
+    try {
+      await shot(send, '99-failure');
+    } catch {
+      /* ignore */
+    }
+  }
+  writeFileSync(`${EVIDENCE}/drive-results.json`, JSON.stringify(report, null, 2));
+  console.log('FAILURES', report.failures.length);
+  try {
+    chrome.kill('SIGTERM');
+  } catch {
+    /* ignore */
+  }
+  ws.close();
+  process.exit(report.failures.length ? 1 : 0);
+}
+
+main().catch((e) => {
+  console.error(e);
+  try {
+    chrome?.kill('SIGTERM');
+  } catch {
+    /* ignore */
+  }
+  process.exit(1);
+});

